def _input_literal(display_name: str, current: Any, choices: list[str]) -> Any:
    """Select from fixed choices — no free text input."""
    choice_labels = list(choices)
    if current is not None and str(current) not in choices:
        choice_labels.insert(0, str(current))
    if current is not None:
        choice_labels.append("Keep existing value")
    answer = questionary.select(
        display_name,
        choices=choice_labels,
        default=str(current) if current is not None and str(current) in choice_labels else choice_labels[0],
    ).ask()
    if answer is None or answer == "Keep existing value":
        return None
    return answer


